examples.features.tom:
from math import gcd, pow

class NegativeError(Error):
    @init
    def make(self, message: str):
        Error.start(self, message)

def square_root_floor(n: int) -> int:
    if n < 0:
        raise NegativeError('no square root of a negative number')
    r = 0
    while (r + 1) * (r + 1) <= n:
        r = r + 1
    return r

@main
def main():
    words = 'the quick brown fox jumps over the lazy dog the end'.split(' ')
    counts: dict[str, int] = {}
    for w in words:
        if w in counts:
            counts[w] = counts[w] + 1
        else:
            counts[w] = 1
    print(counts['the'], len(counts))
    seen: set[str] = {}
    for w in words:
        seen.add(w)
    print(len(seen), 'fox' in seen)
    print(gcd(84, 36), pow(2, 20))
    for n in [16, 17, 0 - 4]:
        try:
            print(n, square_root_floor(n))
        catch NegativeError as e:
            print(n, 'error:', e.message)
        finally:
            print('checked', n)
    total = 0
    for i in range(100):
        if i % 2 == 1:
            continue
        if i > 10:
            break
        total = total + i
    print(total)

examples.objects.tom:
# Heap values the compiler allocates and frees by reference counting (D36a).
# tomato build examples/objects.tom -o objects && ./objects 5
class Item:
    name: str = ''
    qty: int = 0

class Inventory:
    items: list[Item] = []

    def add(self, name: str, qty: int):
        item = Item()
        item.name = name
        item.qty = qty
        self.items.append(item)

    def total(self) -> int:
        t = 0
        for item in self.items:
            t = t + item.qty
        return t

    def describe(self) -> str:
        s = ''
        for item in self.items:
            s = s + item.name + 'x' + str(item.qty) + ' '
        return s

@main
def main(n: int):
    inv = Inventory()
    for i in range(n):
        inv.add('item' + str(i), i * 2)
    print(inv.describe())
    print('total', inv.total(), 'chars', len(inv.describe()))

